import * as React from 'react';
import { cn } from '@/lib/utils';

export type FeatureRowProps = Omit<React.HTMLAttributes<HTMLDivElement>, 'title'> & {
  /** Row heading. */
  title: React.ReactNode;
  /** Supporting copy. */
  description?: React.ReactNode;
  /** Small overline above the heading. */
  eyebrow?: React.ReactNode;
  /** Calls to action. */
  actions?: React.ReactNode;
  /** Image, mockup, video or form shown beside the copy. */
  media: React.ReactNode;
  /** Which side the media sits on at lg and up. Default 'right'. */
  mediaPosition?: 'left' | 'right';
  /** Heading level. Default 2. */
  level?: 2 | 3;
  /** Heading scale. Default 'md'. */
  size?: 'md' | 'lg';
};

const titleSizes = {
  md: 'text-3xl',
  lg: 'text-3xl sm:text-4xl',
} as const;

/**
 * Alternating media and copy row for feature sections. Unlike Hero, this is a
 * mid-page block with a smaller heading and no h1. Use several rows to explain
 * a workflow, product surface or audience benefit.
 */
export const FeatureRow = React.forwardRef<HTMLDivElement, FeatureRowProps>(function FeatureRow(
  {
    title,
    description,
    eyebrow,
    actions,
    media,
    mediaPosition = 'right',
    level = 2,
    size = 'md',
    className,
    ...props
  },
  ref
) {
  const Heading = `h${level}` as 'h2' | 'h3';

  return (
    <div
      ref={ref}
      className={cn('grid items-center gap-10 lg:grid-cols-2 lg:gap-16', className)}
      {...props}
    >
      <div className={cn('min-w-0', mediaPosition === 'left' && 'lg:order-2')}>
        {eyebrow && (
          <p className="mb-3 text-xs font-semibold uppercase tracking-widest text-primary">{eyebrow}</p>
        )}
        <Heading className={cn('font-semibold tracking-tight text-balance', titleSizes[size])}>{title}</Heading>
        {description && (
          <div className="mt-4 max-w-xl text-base leading-relaxed text-muted-foreground sm:text-lg">
            {description}
          </div>
        )}
        {actions && <div className="mt-7 flex flex-wrap items-center gap-3">{actions}</div>}
      </div>
      <div className={cn('min-w-0', mediaPosition === 'left' && 'lg:order-1')}>{media}</div>
    </div>
  );
});

{
  "id": "feature-row",
  "name": "FeatureRow",
  "tier": "organism",
  "package": "@slipstream-ui/core",
  "importPath": "@slipstream-ui/core",
  "version": "0.6.1",
  "sourceDir": "feature-row",
  "exportName": "FeatureRow",
  "description": "Alternating media and copy row for mid-page feature sections.",
  "designIntent": "Landing pages alternate a product shot with a short feature story. FeatureRow owns the two-column rhythm and media side without taking over the page h1, which belongs to Hero or PageHeader.",
  "props": [
    {
      "name": "title",
      "type": "ReactNode",
      "required": true,
      "description": "Row heading."
    },
    {
      "name": "description",
      "type": "ReactNode",
      "required": false,
      "description": "Supporting copy."
    },
    {
      "name": "eyebrow",
      "type": "ReactNode",
      "required": false,
      "description": "Small overline above the heading."
    },
    {
      "name": "actions",
      "type": "ReactNode",
      "required": false,
      "description": "Calls to action."
    },
    {
      "name": "media",
      "type": "ReactNode",
      "required": true,
      "description": "Image, mockup, video or form shown beside the copy."
    },
    {
      "name": "mediaPosition",
      "type": "'left' | 'right'",
      "required": false,
      "defaultValue": "right",
      "enum": [
        "left",
        "right"
      ],
      "description": "Which side the media sits on at lg and up."
    },
    {
      "name": "level",
      "type": "2 | 3",
      "required": false,
      "defaultValue": "2",
      "description": "Heading level."
    },
    {
      "name": "size",
      "type": "'md' | 'lg'",
      "required": false,
      "defaultValue": "md",
      "enum": [
        "md",
        "lg"
      ],
      "description": "Heading scale."
    }
  ],
  "examples": [
    {
      "title": "Alternating feature",
      "code": "<FeatureRow\n  eyebrow=\"For advisors\"\n  title=\"Reach relevant investors\"\n  description=\"Run a confidential, data-informed process.\"\n  media={<img src=\"/deal-flow.png\" alt=\"Deal flow dashboard\" />}\n  actions={<Button>Request access</Button>}\n/>",
      "description": "A standard feature row with media on the right."
    }
  ],
  "antiPatterns": [
    {
      "title": "Don't use FeatureRow for the page hero",
      "explanation": "Use Hero for the opening story and h1. FeatureRow defaults to h2 and is intended for mid-page sections.",
      "example": "// Avoid\n<FeatureRow title=\"Page title\" />\n\n// Prefer\n<Hero title=\"Page title\" />"
    }
  ],
  "accessibility": [
    {
      "feature": "Heading level",
      "implementation": "Renders h2 by default and accepts level 3",
      "userRequirements": "Keep the outline sequential under the page h1"
    },
    {
      "feature": "Media alternative",
      "implementation": "Media is a slot; the consumer owns alt text",
      "userRequirements": "Give informative media alt text and hide decorative media"
    }
  ],
  "compositionRules": [
    {
      "component": "Section",
      "relationship": "Place FeatureRow inside a Section, usually three to five in sequence",
      "example": "<Section><FeatureRow title=\".\" media={<Media />} /></Section>"
    }
  ],
  "relatedComponents": [
    "Hero",
    "FeatureGrid",
    "Section"
  ]
}
